def enrol_current_trials(apps, schema_editor):
    """Landlords the street team signed up before this shipped are on the
    old 30-day Starter trial. Enrol everyone whose trial is still running
    (Membership.apply_founding's trial branch, inlined since migrations
    get the historical model without its methods). Expired trials and
    suspended accounts are left for staff to enrol case by case via the
    admin action."""
    if not founding.programme_open():
        return

    Membership = apps.get_model("accounts", "Membership")
    now = timezone.now()

    Membership.objects.filter(
        is_trial=True,
        trial_end__gte=now,
        status="active",
        is_active=True,
        user__is_active=True,
    ).update(
        is_founding=True,
        founding_since=now,
        tier="gold",
        trial_end=founding.free_until(),
    )


